-- Refresh Island Grill menu from 7krave (restaurant 97): replace the stale
-- 81-item menu on all 4 branches with the current 65-item 7krave menu
-- (correct names, prices, options). Reversible via the *_backup_20261106 tables.
BEGIN;

-- 1. Back up existing menu + options for all 4 branches
CREATE TABLE IF NOT EXISTS ig_menu_backup_20261106 AS
  SELECT * FROM menus WHERE restaurant_id IN ('398bc618-a847-4eda-b7e7-0e14184b08a2','c28b314c-267e-48f6-b62d-9c45fd9fa792','047d9016-8deb-4fb7-89d9-59429914a70e','207d2253-296d-4873-835f-db91b95cffc3');
CREATE TABLE IF NOT EXISTS ig_optgroup_backup_20261106 AS
  SELECT g.* FROM menu_option_groups g JOIN menus m ON m.id=g.menu_item_id
  WHERE m.restaurant_id IN ('398bc618-a847-4eda-b7e7-0e14184b08a2','c28b314c-267e-48f6-b62d-9c45fd9fa792','047d9016-8deb-4fb7-89d9-59429914a70e','207d2253-296d-4873-835f-db91b95cffc3');
CREATE TABLE IF NOT EXISTS ig_optchoice_backup_20261106 AS
  SELECT c.* FROM menu_option_choices c
  JOIN menu_option_groups g ON g.id=c.group_id
  JOIN menus m ON m.id=g.menu_item_id WHERE m.restaurant_id IN ('398bc618-a847-4eda-b7e7-0e14184b08a2','c28b314c-267e-48f6-b62d-9c45fd9fa792','047d9016-8deb-4fb7-89d9-59429914a70e','207d2253-296d-4873-835f-db91b95cffc3');

-- 2. Delete existing Island Grill menu (choices -> groups -> items)
DELETE FROM menu_option_choices WHERE group_id IN (
  SELECT g.id FROM menu_option_groups g JOIN menus m ON m.id=g.menu_item_id
  WHERE m.restaurant_id IN ('398bc618-a847-4eda-b7e7-0e14184b08a2','c28b314c-267e-48f6-b62d-9c45fd9fa792','047d9016-8deb-4fb7-89d9-59429914a70e','207d2253-296d-4873-835f-db91b95cffc3'));
DELETE FROM menu_option_groups WHERE menu_item_id IN (
  SELECT id FROM menus WHERE restaurant_id IN ('398bc618-a847-4eda-b7e7-0e14184b08a2','c28b314c-267e-48f6-b62d-9c45fd9fa792','047d9016-8deb-4fb7-89d9-59429914a70e','207d2253-296d-4873-835f-db91b95cffc3'));
DELETE FROM menus WHERE restaurant_id IN ('398bc618-a847-4eda-b7e7-0e14184b08a2','c28b314c-267e-48f6-b62d-9c45fd9fa792','047d9016-8deb-4fb7-89d9-59429914a70e','207d2253-296d-4873-835f-db91b95cffc3');

